            >
              {mod.tag}
            </div>
          )}
        </div>
        <div
          style={{
            fontFamily: FONT.sans,
            fontSize: 14,
            fontWeight: 700,
            color: BRAND.onyx,
            letterSpacing: "-0.01em",
            marginBottom: 4,
          } as React.CSSProperties}
        >
          {mod.name}
        </div>
        <div
          style={{
            fontFamily: FONT.sans,
            fontSize: 12,
            color: BRAND.stoneLight,
            lineHeight: 1.4,
          } as React.CSSProperties}
        >
          {mod.desc}
        </div>
      </div>
    </motion.a>
  );
}

// ── CategoryCard ──────────────────────────────────────────────────────────────

interface CategoryCardProps {
  accent: "rust" | "amber" | "sage";
  title: string;
  modules: string;
  body: string;
  link: { label: string; href: string };
}

const categoryAccentMap = {
