      />
      {/* Corner glow */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          top: 0, right: 0,
          width: 140, height: 140,
          background: `radial-gradient(circle at 100% 0%, ${a.wash} 0%, transparent 70%)`,
          pointerEvents: "none",
