      />
      <div style={{ position: "relative" } as React.CSSProperties}>
        <h3
          style={{
            fontFamily: FONT.sans,
            fontSize: 20,
            fontWeight: 700,
            color: BRAND.onyx,
            letterSpacing: "-0.015em",
            marginBottom: 6,
            lineHeight: 1.2,
          } as React.CSSProperties}
        >
          {title}
        </h3>
        <div
          style={{
            display: "inline-flex",
            padding: "3px 10px",
            borderRadius: 100,
            background: a.soft,
            fontFamily: FONT.mono,
            fontSize: 10,
