            lineHeight: 1.65,
            color: BRAND.stoneDark,
            margin: 0,
          } as React.CSSProperties}
        >
          {body}
        </p>
      </div>
      <a
        href={link.href}
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: 6,
          fontFamily: FONT.sans,
          fontSize: 13,
          fontWeight: 600,
          color: a.color,
          textDecoration: "none",
          marginTop: "auto",
        } as React.CSSProperties}
      >
        {link.label}
        <ArrowRight size={13} strokeWidth={2.2} />
      </a>
    </motion.div>
  );
}

// ── Page ──────────────────────────────────────────────────────────────────────

